#include "z80_core.hh"
#include "z80.inc"
#include <cassert>
#include <utility>

namespace MameZ80
{

int z80_device::standard_irq_callback(int, u16)
{
	m_irqack_cb(1);
	return m_irqVector ? m_irqVector() : 0xff;
}

#include "z80_alu.inc"

void z80_device::execute_run()
{
#include "z80.hxx"
}

z80_device::z80_device() = default;

void z80_device::setMemHandlers(u8 (*read)(u16), void (*write)(u16, u8))
{
	m_data.read = m_opcodes.read = m_args.read = read;
	m_data.write = m_opcodes.write = m_args.write = write;
}

void z80_device::setIoHandlers(u8 (*read)(u16), void (*write)(u16, u8))
{
	m_io.read = read;
	m_io.write = write;
}

void z80_device::setIrqVectorCallback(u8 (*cb)())
{
	m_irqVector = cb;
}

void z80_device::reset()
{
	leave_halt();
	m_ref = 0xffff00;
	PC = 0;
	WZ = 0;
	m_i = 0;
	m_r = 0;
	m_r2 = 0;
	m_iff1 = 0;
	m_iff2 = 0;
	m_halt = 0;
	m_im = 0;
	m_nmi_state = 0;
	m_irq_state = 0;
	m_wait_state = 0;
	m_busreq_state = 0;
	m_busack_state = 0;
	m_ea = 0;
	m_service_attention = 0;
	IX = IY = 0xffff;
	m_f = {};
	m_f.z_val = 0;
	set_service_attention<SA_NMI_PENDING, 0>();
	set_service_attention<SA_AFTER_EI, 0>();
	set_service_attention<SA_AFTER_LDAIR, 0>();
}

void z80_device::run(int cycles)
{
	if(cycles <= 0)
		return;
	m_icount = cycles;
	execute_run();
}

void z80_device::setIrq(bool asserted)
{
	m_irq_state = asserted ? ASSERT_LINE : CLEAR_LINE;
	if(asserted)
		set_service_attention<SA_IRQ_ON, true>();
	else
		set_service_attention<SA_IRQ_ON, false>();
}

void z80_device::pulseNmi()
{
	set_service_attention<SA_NMI_PENDING, 1>();
	m_nmi_state = ASSERT_LINE;
}

u16 z80_device::af() const
{
	u8 f = 0;
	f |= m_f.s();
	f |= m_f.z();
	f |= m_f.yx();
	f |= m_f.h();
	f |= m_f.pv();
	f |= m_f.n ? NF : 0;
	f |= m_f.c ? CF : 0;
	return u16((A << 8) | f);
}

void z80_device::setRegisters(u16 pc, u16 sp, u16 afIn, u16 bc, u16 de, u16 hl,
	u16 ix, u16 iy, u16 wz, u16 af2, u16 bc2, u16 de2, u16 hl2,
	u8 r, u8 r2, u8 iReg, u8 im, u8 haltFlag, u8 iff1, u8 iff2, u8 irq, u8 nmi)
{
	PC = pc;
	SP = sp;
	BC = bc;
	DE = de;
	HL = hl;
	IX = ix;
	IY = iy;
	WZ = wz;
	m_af2.w = af2;
	m_bc2.w = bc2;
	m_de2.w = de2;
	m_hl2.w = hl2;
	m_r = r;
	m_r2 = r2;
	m_i = iReg;
	m_im = im & 3;
	m_halt = haltFlag;
	m_iff1 = iff1;
	m_iff2 = iff2;
	m_irq_state = irq;
	m_nmi_state = nmi;
	A = afIn >> 8;
	set_f(u8(afIn));
	m_ref = 0xffff00;
}

}
